/* ---------- CJHQ resource matcher ----------
   Pure client-side scoring over the resource index already on the page. No AI
   and no network call, so it works today and the AI layer can call it later. */
// How many resource titles contain this word. Cached because it is stable for
// the life of the page and called once per word per resource.
let __askTitleFreq = null;
function askTitleFrequency(word){
  if(!__askTitleFreq){
    __askTitleFreq = Object.create(null);
    (typeof categories !== 'undefined' ? categories : []).forEach(cat=>{
      (cat.groups || []).forEach(g=>{
        (g.items || []).forEach(it=>{
          const seen = new Set(
            cjhqNormalizeSearch((String(it.en || '') + ' ' + String(it.fr || '')).toLowerCase())
              .split(/\s+/).filter(Boolean));
          seen.forEach(w => { __askTitleFreq[w] = (__askTitleFreq[w] || 0) + 1; });
        });
      });
    });
  }
  return __askTitleFreq[word] || 0;
}

/* ---------- Hebrew/Yiddish term bridge ----------
   The resource matcher scores on [a-z0-9] only, so a question written in
   Hebrew or Yiddish script produced no words at all and matched nothing - the
   same passport question answered in English and failed in Hebrew.

   This maps script and transliterated terms onto the English keyword the
   resource index already uses. It adds no resources and no facts: it only lets
   a Yiddish or Hebrew question reach the SAME CJHQ resource an English one
   reaches, which is what section 11 requires. */
const ASK_TERM_BRIDGE = [
  [/\u05e4\u05d0\u05e1\u05e4\u05d0\u05e8\u05d8|\u05e4\u05e2\u05e1\u05e4\u05d0\u05e8\u05d8|\u05d3\u05e8\u05db\u05d5\u05df|paspart/i, 'passport'],
  [/\u05e0\u05e2\u05e7\u05e1\u05d5\u05e1/i,                                   'nexus'],
  [/\u05d5\u05d5\u05d9\u05d6\u05e2|\u05d5\u05d9\u05d6\u05d4/i,                                 'visa'],
  [/\u05e8\u05d9\u05d9\u05d6|\u05e8\u05d9\u05d9\u05d6\u05df|\u05e0\u05e1\u05d9\u05e2\u05d4|\u05e0\u05e1\u05d9\u05e2\u05d5\u05ea|\u05d2\u05e8\u05e2\u05e0\u05d9\u05e5/i,                'travel border'],
  [/\u05e4\u05d0\u05e8\u05e7\u05df|\u05e4\u05d0\u05e8\u05e7\u05d9\u05e0\u05d2|\u05d7\u05e0\u05d9\u05d4/i,                          'parking permit'],
  [/\u05e9\u05e0\u05d9\u05d9|\u05e9\u05e0\u05d9\u05d9\u05e2\u05df|\u05e9\u05dc\u05d2/i,                                'snow removal'],
  [/\u05e7\u05d9\u05e0\u05d3|\u05e7\u05d9\u05e0\u05d3\u05e2\u05e8|\u05d9\u05dc\u05d3|\u05d9\u05dc\u05d3\u05d9\u05dd/i,                            'child'],
  [/\u05d2\u05e2\u05d1\u05d5\u05e8\u05d8\u05e1|\u05dc\u05d9\u05d3\u05d4/i,                                 'birth certificate'],
  [/\u05e8\u05d0\u05de\u05e7|\u05e8\u05e2\u05d2\u05d9\u05e2|\u05e7\u05e8\u05d0\u05e0\u05e7\u05df|\u05d1\u05e8\u05d9\u05d0\u05d5\u05ea/i,                        'ramq health insurance'],
  [/\u05d3\u05e8\u05d9\u05d9\u05d5\u05d5\u05e2\u05e8|\u05e4\u05d9\u05e8\u05e2\u05e8\u05e9\u05d9\u05d9\u05df|\u05e0\u05d4\u05d9\u05d2\u05d4/i,                        'driver license'],
  [/\u05d1\u05d9\u05e8\u05d2\u05e2\u05e8\u05e9\u05d0\u05e4\u05d8|\u05d0\u05d6\u05e8\u05d7\u05d5\u05ea/i,                           'citizenship'],
  [/\u05d0\u05d9\u05de\u05d9\u05d2\u05e8\u05d0\u05e6\u05d9\u05e2|\u05d4\u05d2\u05d9\u05e8\u05d4/i,                             'immigration'],
  [/\u05e9\u05d8\u05d9\u05d9\u05e2\u05e8\u05df|\u05de\u05e1\u05d9\u05dd/i,                                 'taxes']
];
function askBridgeTerms(question){
  const s = String(question || '');
  const add = [];
  ASK_TERM_BRIDGE.forEach(pair => { if(pair[0].test(s)) add.push(pair[1]); });
  return add.join(' ');
}

function askMatchResources(question, limit){
  // The bridge only ever appends English keywords; the original question is
  // left intact, so English and French matching is byte-for-byte unchanged.
  const bridged = String(question || '') + ' ' + askBridgeTerms(question);
  const q = cjhqNormalizeSearch(bridged.toLowerCase());
  if(q.length < 2) return [];
  // Common words appear in nearly every description, so two of them together
  // were enough to fake a match - "what is the capital of Peru" scored on
  // "what" and "the" alone. Strip them before scoring.
  const STOP = new Set(['the','and','for','you','your','can','how','where','when','with','from',
    'are','this','that','need','get','find','about','does','any','has','have','what','who','why',
    'was','were','will','would','should','could','there','their','they','been','into','than','then',
    'them','some','more','most','also','just','like','want','looking','know','tell','please','info',
    'information','help','question','anything','something',
    // French equivalents - a French question deserves the same filtering.
    'les','des','une','pour','dans','avec','sur','est','sont','que','qui','quoi','comment','puis',
    'peux','peut','vous','nous','mon','mes','mon','notre','avoir','faire','besoin','trouver','obtenir',
    'demander','cette','cet','ceci','cela','plus','tout','tous','toute','ainsi','aussi','renseignement',
    'renseignements','aide','ou']);
  // Transliterated Yiddish function words, for the same reason as the English
  // and French entries above: "vu ken ikh find passport information?" is a
  // passport question, but "ken" and "ikh" inflated the word count and pushed
  // coverage below the threshold, so it matched nothing.
  //
  // Applied ONLY when the question is actually Yiddish. Folding these into the
  // shared list changed an English answer - "How far is the airport from
  // Outremont?" stopped being a refusal and started matching a parking
  // resource, because "far" was no longer counted. English and French matching
  // has to stay exactly as it was.
  const YI_STOP = new Set(['ken','ikh','vu','vos','ver','ven','darf','vil','visn','wissen',
    'nisht','azoy','haynt','morgn','farvos','vifl','rufn','rufen','bakumen','betn','zukhn',
    'iz','zenen','zayn','kenen','oykh','epes','shoyn','undz','aykh','gefinen','far','mit',
    'dos','der','mir','tsu','ober','nit','veln']);
  const isYi = askDetectLanguage(question) === 'yi';
  // French elides constantly - "j'ai", "d'information", "l'enfant". Stripping the
  // apostrophe glued them into "jai" and "dinformation", which no stopword list
  // catches, so they inflated the word count and pushed real matches below the
  // coverage threshold. Split on the apostrophe first.
  const words = q.replace(/[\u2019']/g, ' ').split(/\s+/)
    .map(w => w.replace(/[^a-z0-9]/g,''))
    .filter(w => w.length > 2 && !STOP.has(w) && !(isYi && YI_STOP.has(w)));
  if(!words.length) return [];
  const out = [];
  (typeof categories !== 'undefined' ? categories : []).forEach(cat=>{
    (cat.groups || []).forEach(g=>{
      (g.items || []).forEach(it=>{
        const hay = cjhqNormalizeSearch([
          it.en, it.fr, it.what_en, it.need_en, it.steps_en,
          it.question_en, it.answer_en, (it.tips_list_en || []).join(' '),
          cat.en, g.heading_en || ''
        ].filter(Boolean).join(' ').toLowerCase());
        // Both titles count. Previously only the English title did, so a French
        // question ("Ou puis-je demander un passeport?") scored a single body hit
        // and fell below the relevance threshold - it matched nothing at all.
        const title = cjhqNormalizeSearch((String(it.en || '') + ' ' + String(it.fr || '')).toLowerCase());
        let score = 0, titleHits = 0, bodyHits = 0;
        words.forEach(w=>{
          if(title.includes(w)){ score += 10; titleHits++; }
          else if(hay.includes(w)){ score += 2; bodyHits++; }
        });
        if(title === q) score += 40;
        // Frequency turned out to be the wrong signal: "passport" appears in 10
        // titles but is exactly what the user means, while "times" appears in
        // only 2 and still produced a nonsense match for "minyan times at my
        // shul". What separates them is COVERAGE - how much of the question the
        // match actually explains. One matched word out of four is a coincidence;
        // one out of one is the question.
        const matched = titleHits + bodyHits;
        const coverage = matched / words.length;
        const relevant = (titleHits > 0 && (words.length <= 2 || coverage >= 0.5))
                       || bodyHits >= 2;
        if(relevant && score > 0) out.push({ score, item: it, category: cat.en });
      });
    });
  });
  out.sort((a,b)=> b.score - a.score);
  // Relevance floor. Being the third-best match is not the same as being
  // relevant: a NEXUS question was pulling in RAMQ, and a RAMQ question was
  // pulling in NEXUS, because both are travel/identity vocabulary. Anything
  // scoring under 55% of the best match is a weaker cousin, not an answer.
  // The top hit is always kept, so no question loses the resource it had.
  const floor = out.length ? out[0].score * 0.70 : 0;
  return out.filter((h, i) => i === 0 || h.score >= floor).slice(0, limit || 3);
}

/* ---------- structured handlers ----------
   Each returns the shared answer shape, or null if it does not apply. Answers
   here are either verifiable links or clearly-labelled "check the source"
   responses - none of them assert a time-sensitive fact from memory. */

/* ---------- language detection ----------
   Decides the language of the QUESTION, which is not the same as the site
   toggle: a French-speaking visitor may still type in English, and Hebrew
   speakers frequently type transliterated Hebrew inside an English sentence.

   Four languages: en, fr, he, yi. Hebrew and Yiddish share the same Unicode
   block, so script alone cannot separate them - a scored comparison does.
   Yiddish is NOT a dialect of Hebrew here and is never answered in Hebrew.

   Deliberately conservative: on a tie the answer is Hebrew, because Hebrew was
   the previous behaviour for all Hebrew-script input and a wrong switch to
   Yiddish is more jarring to a Hebrew speaker than the reverse.              */

/* Words that are Yiddish and not Hebrew. Weight 2 unless noted. Kept as a
   plain list so a Yiddish speaker can extend it without reading the code. */
const ASK_YI_WORDS = [
  // question words and pronouns
  '\u05d5\u05d5\u05d0\u05e1','\u05d5\u05d5\u05d0\u05b8\u05e1','\u05d5\u05d5\u05e2\u05e8','\u05d5\u05d5\u05d9','\u05d5\u05d5\u05d0\u05d5','\u05d5\u05d5\u05e2\u05df','\u05e4\u05d0\u05e8\u05d5\u05d5\u05d0\u05e1','\u05e4\u05d0\u05e8\u05d5\u05d5\u05d0\u05b8\u05e1','\u05d5\u05d5\u05d9\u05e4\u05dc',
  '\u05d0\u05d9\u05e8','\u05de\u05d9\u05e8','\u05d0\u05d5\u05e0\u05d6','\u05d0\u05d5\u05e0\u05d3\u05d6','\u05d6\u05d9\u05d9','\u05de\u05d9\u05d9\u05df','\u05de\u05d9\u05d9\u05e0\u05e2','\u05d0\u05d9\u05d9\u05e2\u05e8','\u05d6\u05d9\u05d9\u05df','\u05de\u05e2\u05df',
  // verbs and modals
  '\u05e7\u05e2\u05df','\u05e7\u05e2\u05e0\u05e2\u05df','\u05d5\u05d5\u05d9\u05dc','\u05d5\u05d5\u05e2\u05dc','\u05d3\u05d0\u05e8\u05e3','\u05d3\u05d0\u05b7\u05e8\u05e3','\u05d4\u05d0\u05d1','\u05d4\u05d0\u05d1\u05df','\u05d0\u05d9\u05d6','\u05d6\u05e2\u05e0\u05e2\u05df','\u05d6\u05d0\u05dc',
  '\u05d5\u05d5\u05d9\u05e1\u05df','\u05d5\u05d5\u05d9\u05e1\u05e0\u05d9\u05e7','\u05e8\u05d5\u05e4\u05df','\u05e8\u05d5\u05e4\u05e2\u05df','\u05d1\u05d0\u05e7\u05d5\u05de\u05e2\u05df','\u05d1\u05e2\u05d8\u05df','\u05d2\u05e2\u05e4\u05d9\u05e0\u05e2\u05df','\u05d6\u05d5\u05db\u05df','\u05e7\u05d5\u05de\u05e2\u05df','\u05d2\u05d9\u05d9\u05df',
  // adverbs, particles, articles
  '\u05d0\u05d6\u05d5\u05d9','\u05e0\u05d9\u05e9\u05d8','\u05e7\u05d9\u05d9\u05df','\u05d3\u05e2\u05e8','\u05d3\u05d0\u05e1','\u05d3\u05d9','\u05e4\u05d5\u05e0\u05e2\u05dd','\u05d0\u05d5\u05d9\u05da','\u05d0\u05d5\u05d9\u05d1','\u05d0\u05d1\u05e2\u05e8','\u05d0\u05d3\u05e2\u05e8',
  '\u05d4\u05d9\u05d9\u05e0\u05d8','\u05de\u05d0\u05e8\u05d2\u05df','\u05de\u05d0\u05e8\u05d2\u05e2\u05df','\u05d9\u05e2\u05e6\u05d8','\u05d3\u05d0\u05e8\u05d8','\u05e2\u05e4\u05e2\u05e1','\u05e9\u05d5\u05d9\u05df','\u05d2\u05d5\u05d8','\u05d1\u05d9\u05d8\u05e2','\u05d3\u05d0\u05e0\u05e7','\u05d3\u05d0\u05e0\u05e7\u05e2\u05df',
  // nouns that are Yiddish rather than Hebrew
  '\u05d0\u05d9\u05e0\u05e4\u05d0\u05e8\u05de\u05d0\u05e6\u05d9\u05e2','\u05e7\u05d9\u05e0\u05d3','\u05e7\u05d9\u05e0\u05d3\u05e2\u05e8','\u05de\u05e2\u05e0\u05d8\u05e9','\u05de\u05e2\u05e0\u05d8\u05e9\u05df','\u05d5\u05d5\u05e2\u05d2\u05df','\u05e8\u05d9\u05d9\u05d6\u05df','\u05e0\u05d5\u05d9\u05d8\u05e4\u05d0\u05dc',
  // Added after a Yiddish halachic question ("\u05d8\u05d0\u05e8 \u05d0\u05d9\u05da \u05de\u05d9\u05d8\u05e0\u05e2\u05de\u05e2\u05df \u05d0\u05df \u05d0\u05ea\u05e8\u05d5\u05d2 \u05dc\u05d5\u05d9\u05d8 \u05d4\u05dc\u05db\u05d4?")
  // scored 0-0 and fell to the Hebrew tie-break. None of these is a Hebrew
  // word and none is religious vocabulary - they are ordinary Yiddish verbs
  // and particles, which is the evidence this classifier is meant to run on.
  '\u05d8\u05d0\u05e8','\u05d8\u05d0\u05e8\u05df','\u05de\u05d9\u05d8\u05e0\u05e2\u05de\u05e2\u05df','\u05dc\u05d5\u05d9\u05d8','\u05d8\u05e8\u05d0\u05d2\u05df','\u05d0\u05e4\u05e2\u05df','\u05d0\u05d5\u05e4\u05df','\u05d8\u05d0\u05df','\u05d1\u05e8\u05e2\u05e0\u05d2\u05e2\u05df',
  '\u05e4\u05e8\u05e2\u05d2\u05d8','\u05e4\u05e8\u05e2\u05d2\u05df','\u05d0\u05e0\u05d3\u05e2\u05e8\u05e2','\u05e2\u05de\u05e2\u05e6\u05e2\u05e8','\u05d6\u05d0\u05dc\u05df','\u05de\u05e2\u05d2\u05dc\u05d9\u05da','\u05e9\u05d9\u05e7\u05df'
];
/* Weight 1: real Yiddish, but each also occurs incidentally elsewhere, so on
   its own it is a hint rather than evidence. */
const ASK_YI_WEAK = ['\u05e4\u05d0\u05e8','\u05de\u05d9\u05d8','\u05d3\u05d0','\u05d0\u05dc\u05e2','\u05e0\u05d0\u05da','\u05d0\u05d5\u05d9\u05e3','\u05d0\u05df','\u05e6\u05d5'];
/* Hebrew function words and question words. */
const ASK_HE_WORDS = [
  '\u05de\u05d4','\u05d0\u05d9\u05e4\u05d4','\u05de\u05ea\u05d9','\u05d4\u05d0\u05dd','\u05db\u05de\u05d4','\u05dc\u05de\u05d4','\u05de\u05d3\u05d5\u05e2','\u05d0\u05d9\u05d6\u05d4','\u05d4\u05d9\u05d5\u05dd','\u05de\u05d7\u05e8','\u05e2\u05db\u05e9\u05d9\u05d5',
  '\u05ea\u05d5\u05d3\u05d4','\u05e9\u05dc\u05d5\u05dd','\u05e6\u05e8\u05d9\u05da','\u05e6\u05e8\u05d9\u05db\u05d9\u05dd','\u05e6\u05e8\u05d9\u05db\u05d4','\u05d0\u05e0\u05d9','\u05d0\u05e0\u05d7\u05e0\u05d5','\u05d0\u05ea\u05dd','\u05d4\u05dd','\u05d4\u05d5\u05d0','\u05d4\u05d9\u05d0',
  '\u05d9\u05e9','\u05e9\u05dc','\u05d0\u05ea','\u05d6\u05d4','\u05d6\u05d0\u05ea','\u05e2\u05dd','\u05e2\u05dc','\u05d2\u05dd','\u05e8\u05e7','\u05db\u05dc','\u05dc\u05d0','\u05db\u05df','\u05d8\u05d5\u05d1','\u05d9\u05db\u05d5\u05dc','\u05d9\u05db\u05d5\u05dc\u05d4',
  '\u05dc\u05d3\u05e2\u05ea','\u05dc\u05d7\u05d3\u05e9','\u05dc\u05d4\u05d2\u05d9\u05e9','\u05dc\u05d9\u05e6\u05d5\u05e8','\u05dc\u05e7\u05d1\u05dc','\u05dc\u05de\u05e6\u05d5\u05d0','\u05d1\u05e7\u05e9\u05d4','\u05dc\u05d2\u05d1\u05d9','\u05d0\u05e4\u05e9\u05e8\u05d5\u05ea'
];
/* Genuinely shared - counted for neither side. \u05d0\u05e4\u05e9\u05e8 is ordinary Hebrew
   ("is it possible") and ordinary Yiddish ("maybe"); \u05d0\u05d9\u05da is Hebrew "how" and
   Yiddish "I"; \u05d0\u05d9\u05df is Hebrew "there is no" and Yiddish "in". Scoring any of
   them would decide the sentence on the weakest available evidence. */
const ASK_SHARED_SCRIPT_WORDS = ['\u05d0\u05e4\u05e9\u05e8','\u05d0\u05d9\u05da','\u05d0\u05d9\u05df','\u05d0'];

/* Latin-script Yiddish. Weight 2 = structural Yiddish with no ordinary English
   or French reading. Weight 1 = plausible but collides with other languages. */
const ASK_YI_LATIN_STRONG = ['ikh','vu','ven','ver','vos','darf','vil','visn','wissen',
  'nisht','azoy','haynt','morgn','farvos','vifl','rufn','rufen','bakumen','betn','zukhn',
  'iz','zenen','zayn','zayne','kenen','oykh','epes','shoyn','undz','aykh','gefinen','noytfal',
  // Section 5 of the brief lists both spellings; "morgn" alone assumed a
  // single orthography, which the brief explicitly warns against.
  'aroys','arois','morgen','vemen','velkhe','tor','toren','loyt'];
const ASK_YI_LATIN_WEAK = ['far','mit','dos','der','ken','mir','tsu','ober','nit','veln'];
/* Community vocabulary is shared across all four languages. Section 6 of the
   brief is explicit: these must never decide the language on their own, so
   they carry no weight at all. "Where can I find Shabbos information?" is an
   English sentence and has to stay one. */
const ASK_COMMUNITY_TERMS = ['shabbos','shabbes','shabbat','yom tov','yontif','yomtov',
  'daven','davening','shkia','chatzos','mincha','maariv','hatzolah','eruv','mikvah',
  'kosher','frum','heimish','simcha','tznius','pesach','sukkos','purim','chanukah',
  'rosh hashana','zmanim','etrog','lulav','matzah','shul','minyan'];

function askScriptTokens(s){
  return String(s || '').split(/[^\u0590-\u05ffa-zA-Z0-9\u2019']+/).filter(Boolean);
}

/* Hebrew-block input: decide Hebrew vs Yiddish on accumulated evidence. */
function askScoreHebrewScript(s){
  const toks = askScriptTokens(s).filter(t => /[\u0590-\u05ff]/.test(t));
  let yi = 0, he = 0;
  const seen = new Set();
  toks.forEach(t=>{
    // Strip nikkud/cantillation before the lookup: pointed Yiddish
    // (\u05de\u05d0\u05b8\u05e0\u05d8\u05e8\u05e2\u05d0\u05b7\u05dc) otherwise matches no lexicon entry at all. The
    // pointed-alef orthography check below still runs on the raw string,
    // so the evidence the pointing itself provides is not lost.
    const w = t.replace(/[\u0591-\u05C7]/g,'').replace(/[^\u0590-\u05FF]/g,'');
    if(!w || seen.has(w)) return;
    seen.add(w);
    if(ASK_SHARED_SCRIPT_WORDS.indexOf(w) >= 0) return;
    if(ASK_YI_WORDS.indexOf(w) >= 0) yi += 2;
    else if(ASK_YI_WEAK.indexOf(w) >= 0) yi += 1;
    else if(ASK_HE_WORDS.indexOf(w) >= 0) he += 2;
  });
  // Orthography. Yiddish writes the digraphs \u05d5\u05d5 and \u05d9\u05d9 constantly and Hebrew
  // rarely; the precomposed ligatures and pointed alef occur in no Hebrew text.
  if(/[\u05f0\u05f1\u05f2]/.test(s))       yi += 3;
  if(/[\u05d0][\u05b7\u05b8]/.test(s))     yi += 3;
  if(/\u05d5\u05d5/.test(s))               yi += 3;
  if(/\u05d9\u05d9/.test(s))               yi += 2;
  // Hebrew plural endings are a nudge only: Yiddish borrows plenty of Hebrew
  // nouns (\u05d6\u05de\u05e0\u05d9\u05dd, \u05e1\u05e4\u05e8\u05d9\u05dd) and would otherwise be penalised for it.
  if(/[\u05d0-\u05ea]{3,}(\u05d9\u05dd|\u05d5\u05ea)(\s|$|[?!.,])/.test(s)) he += 1;
  return { yi, he };
}

/* Latin-script input: does this look like transliterated Yiddish? */
function askScoreLatinYiddish(s){
  const toks = String(s || '').toLowerCase().split(/[^a-z']+/).filter(Boolean);
  const low = ' ' + String(s || '').toLowerCase() + ' ';
  let score = 0, strong = 0;
  const seen = new Set();
  toks.forEach(t=>{
    if(seen.has(t)) return;
    seen.add(t);
    if(ASK_COMMUNITY_TERMS.indexOf(t) >= 0) return;   // never decisive
    if(ASK_YI_LATIN_STRONG.indexOf(t) >= 0){ score += 2; strong++; }
    else if(ASK_YI_LATIN_WEAK.indexOf(t) >= 0){ score += 1; }
  });
  ASK_COMMUNITY_TERMS.forEach(t=>{ if(t.indexOf(' ') > 0 && low.indexOf(' '+t+' ') >= 0){ /* no weight */ } });
  return { score, strong };
}

function askDetectLanguage(q){
  const s = String(q || '');

  if(/[\u0590-\u05ff]/.test(s)){
    // Mixed input: a single Hebrew-script word inside an otherwise English
    // sentence does not make the sentence Hebrew or Yiddish. Section 6 asks for
    // the dominant conversational language, so measure it before scoring.
    const toks = askScriptTokens(s);
    const heb  = toks.filter(t => /[\u0590-\u05ff]/.test(t)).length;
    const dominant = toks.length ? (heb / toks.length) : 1;
    if(dominant >= 0.34){
      const sc = askScoreHebrewScript(s);
      return sc.yi > sc.he ? 'yi' : 'he';   // tie -> Hebrew, the safer default
    }
    // Otherwise fall through and classify the Latin majority.
  }

  // French markers: accents, elisions, and common question words. Checked as
  // whole words so "est" does not fire on "interest".
  const frWords = /\b(est|es-tu|quand|comment|pourquoi|quel|quelle|quels|quelles|o\u00f9|puis|peux|peut|dois|faut|besoin|trouver|obtenir|demander|prier|nourriture|heure|aujourd|demain|cette|mon|ma|mes|notre|votre|nous|vous|je|j'ai|c'est|qu'est|s'il|de la|du|des|le|la|les|une|un|pour|avec|dans|sur)\b/gi;
  const frAccents = /[\u00e0\u00e2\u00e4\u00e7\u00e8\u00e9\u00ea\u00eb\u00ee\u00ef\u00f4\u00f6\u00f9\u00fb\u00fc]/;
  // Some words are decisive on their own: no English question begins with
  // "Comment", "Quand", "Pourquoi" or "Est-ce que". Without this, short French
  // questions with no accent - "Comment contacter Hatzolah?" - were read as
  // English and answered in English. Checked before Yiddish so that French
  // "vos" ("vos documents") cannot be read as Yiddish "vos" ("what").
  const frStrong = /\b(comment|quand|pourquoi|o\u00f9|quelle?s?|est-ce que|puis-je|peut-on|combien|qu'est-ce)\b/i;
  if(frStrong.test(s)) return 'fr';

  // Transliterated Yiddish. Requires one structural word AND corroboration:
  // a single "far" or "ken" in an English sentence is not evidence.
  const yl = askScoreLatinYiddish(s);
  if(yl.strong >= 1 && yl.score >= 3) return 'yi';

  const hits = (s.match(frWords) || []).length;
  // Otherwise: two French function words, or one plus an accent. A single "le"
  // or "de" inside an English sentence is not enough.
  if(hits >= 2 || (hits >= 1 && frAccents.test(s))) return 'fr';
  return 'en';
}

/* Pick the right string from a {en, fr, he, yi} object.

   A missing translation still degrades to English rather than to blank, but it
   is recorded rather than swallowed: __askMissingYi is what the admin test
   panel and the test suite read to prove no user-facing string is silently
   answering a Yiddish question in English. */
const __askMissingYi = new Set();
function askT(obj, lang){
  if(typeof obj === 'string') return obj;
  if(!obj) return '';
  if(obj[lang]) return obj[lang];
  if(lang === 'yi' && !obj.yi) __askMissingYi.add(String(obj.en || '').slice(0, 120));
  return obj.en || '';
}

function askAnswerShape(){
  return { answer:'', sources:[], actions:[], timeSensitive:false, handled:false, handler:'', lang:'en', location:'', halachic:false };
}

/* ---------- halachic-question guard ----------
   CJHQ is not a religious authority. Before this existed, "Can I carry in the
   eruv on Shabbos according to halacha?" reached askEruv and came back with
   the eruv STATUS answer - silently answering a halachic question with a
   practical one. That is the failure this guard prevents.

   It does not refuse. It runs the practical handlers, presents whatever CJHQ
   actually knows under a clear label, and adds a referral for the ruling
   itself. No rabbi, organisation, phone number or directory is named: CJHQ has
   no verified rabbinic directory, and inventing one is the same failure mode
   as an invented emergency number.

   Deliberately narrow. Mentioning Shabbos, eruv, mikvah, kosher, tefillin,
   mezuzah, an etrog or a yom tov is NOT halachic framing - those are the
   ordinary subjects of practical questions. The trigger requires the user to
   be asking for the ruling: an explicit halachic adjective, "according to
   halacha" and its equivalents, or mutar / assur / \u05d8\u05d0\u05e8 \u05de\u05e2\u05df.                  */
const ASK_HALACHIC_RE = new RegExp([
  // English - adjective forms, explicit "according to" framing, and loanwords
  // that are only ever used to ask for a ruling.
  'halach(?:ic|ically|ik)\\b', 'halakh(?:ic|ically)\\b',
  'according to (?:the )?halach', 'according to (?:the )?halakh',
  'according to jewish law', 'under jewish law', 'per halach',
  '\\bmutar\\b', '\\bassur\\b', '\\bpsak\\b', '\\bposek\\b', '\\bshaila\\b', '\\bsheilah\\b',
  // French
  'selon la halach', 'selon la halakh', 'halakhique', 'halachique',
  'selon la loi juive', 'apr\u00e8s la halach', 'apres la halach',
  // Hebrew - the framing only. Never the bare word \u05d4\u05dc\u05db\u05d4 and never bare
  // \u05de\u05d5\u05ea\u05e8, because "\u05d4\u05d0\u05dd \u05de\u05d5\u05ea\u05e8 \u05dc\u05d7\u05e0\u05d5\u05ea \u05db\u05d0\u05df?" is a parking question.
  '\u05e2\u05dc \u05e4\u05d9 \u05d4\u05d4\u05dc\u05db\u05d4', '\u05e2\u05dc \u05e4\u05d9 \u05d4\u05dc\u05db\u05d4', '\u05dc\u05e4\u05d9 \u05d4\u05d4\u05dc\u05db\u05d4', '\u05dc\u05e4\u05d9 \u05d4\u05dc\u05db\u05d4',
  '\u05de\u05d4 \u05d4\u05d4\u05dc\u05db\u05d4', '\u05e4\u05e1\u05e7 \u05d4\u05dc\u05db\u05d4', '\u05d4\u05dc\u05db\u05ea\u05d9\u05ea', '\u05e9\u05d0\u05dc\u05d4 \u05d4\u05dc\u05db\u05ea\u05d9\u05ea',
  // Yiddish
  '\u05dc\u05d5\u05d9\u05d8 \u05d4\u05dc\u05db\u05d4', '\u05dc\u05d5\u05d9\u05d8 \u05d3\u05e2\u05e8 \u05d4\u05dc\u05db\u05d4', '\u05dc\u05d5\u05d9\u05d8 \u05d3\u05d9 \u05d4\u05dc\u05db\u05d4',
  '\u05d8\u05d0\u05e8 \u05de\u05e2\u05df', '\u05d8\u05d0\u05e8 \u05d0\u05d9\u05da', '\u05d8\u05d0\u05e8 \u05d0\u05d9\u05e8', '\u05d0\u05d9\u05d6 \u05d3\u05d0\u05e1 \u05de\u05d5\u05ea\u05e8', '\u05d4\u05dc\u05db\u05ea\u05d9\u05e9\u05e2'
].join('|'), 'i');

/* The practical chain, named once so the guard and the entry point cannot
   drift apart. askHalachic is NOT in it - it runs ahead of it. */

/* ---------- FindMTL fallback ----------
   Runs LAST, after every CJHQ handler and after the resource matcher, so CJHQ's
   own content always wins first. It only fires for the categories FindMTL
   actually covers; anything else still reaches the plain decline, because "we
   do not have that" is a better answer than a directory that will not have it
   either.                                                                     */
const ASK_FINDMTL_MATCH = [
  { key:'border',        match:/border wait|wait time|wait at the border|temps d\u2019attente|attente \u00e0 la fronti\u00e8re|\u05d6\u05de\u05df \u05d4\u05de\u05ea\u05e0\u05d4|\u05d5\u05d5\u05d0\u05e8\u05d8\u05df \u05d1\u05d9\u05d9\u05dd \u05d2\u05e8\u05e2\u05e0\u05d9\u05e5/i },
  { key:'organizations', match:/organi[sz]ation|organisme|\u05d0\u05e8\u05d2\u05d5\u05df|\u05d0\u05e8\u05d2\u05d5\u05e0\u05d9\u05dd|\u05d0\u05e8\u05d2\u05d0\u05e0\u05d9\u05d6\u05d0\u05e6\u05d9/i },
  { key:'countries',     match:/\bcamp\b|\bcamps\b|out of town|out-of-town|out of country|colonie de vacances|\u05e7\u05e2\u05de\u05e4|\u05de\u05d7\u05e0\u05d4|\u05de\u05d7\u05e0\u05d5\u05ea/i },
  { key:'travel',        match:/travel directory|community travel|\u05de\u05d3\u05e8\u05d9\u05da \u05e0\u05e1\u05d9\u05e2\u05d5\u05ea/i },
  { key:'eruv',          match:/eruv|eiruv|erouv|\u05e2\u05d9\u05e8\u05d5\u05d1/i },
  { key:'home',          match:/community directory|directory|listing|\u05de\u05d3\u05e8\u05d9\u05da \u05e7\u05d4\u05d9\u05dc\u05d4|\u05e8\u05e9\u05d9\u05de\u05d4|\u05d3\u05d9\u05e8\u05e2\u05e7\u05d8\u05d0\u05e8\u05d9\u05e2|r\u00e9pertoire/i }
];

function askFindMtl(q){
  const s = String(q || '');
  const hit = ASK_FINDMTL_MATCH.find(m => m.match.test(s));
  if(!hit) return null;
  const r = askAnswerShape();
  const L = askDetectLanguage(s); r.lang = L;
  r.handler = 'FindMTL';
  r.handled = false;          // this is a hand-off, not a CJHQ answer
  r.timeSensitive = true;
  r.answer = askT({
    en:'CJHQ does not have current information for that. FindMTL is the community directory that does - the link below goes to the right section. CJHQ does not maintain it, so check the details there.',
    fr:'Le CJHQ n\u2019a pas de renseignements \u00e0 jour l\u00e0-dessus. FindMTL est le r\u00e9pertoire communautaire qui en a \u2014 le lien ci-dessous m\u00e8ne \u00e0 la bonne section. Le CJHQ ne le tient pas \u00e0 jour; v\u00e9rifiez les d\u00e9tails sur place.',
    he:'\u05dc-CJHQ \u05d0\u05d9\u05df \u05de\u05d9\u05d3\u05e2 \u05e2\u05d3\u05db\u05e0\u05d9 \u05e2\u05dc \u05db\u05da. FindMTL \u05d4\u05d5\u05d0 \u05de\u05d3\u05e8\u05d9\u05da \u05d4\u05e7\u05d4\u05d9\u05dc\u05d4 \u05e9\u05d9\u05e9 \u05dc\u05d5 \u2014 \u05d4\u05e7\u05d9\u05e9\u05d5\u05e8 \u05e9\u05dc\u05d4\u05dc\u05df \u05de\u05d5\u05d1\u05d9\u05dc \u05dc\u05de\u05d3\u05d5\u05e8 \u05d4\u05de\u05ea\u05d0\u05d9\u05dd. CJHQ \u05d0\u05d9\u05e0\u05d5 \u05de\u05ea\u05d7\u05d6\u05e7 \u05d0\u05d5\u05ea\u05d5; \u05d9\u05e9 \u05dc\u05d1\u05d3\u05d5\u05e7 \u05e9\u05dd \u05d0\u05ea \u05d4\u05e4\u05e8\u05d8\u05d9\u05dd.',
    yi:'CJHQ \u05d4\u05d0\u05d8 \u05e0\u05d9\u05e9\u05d8 \u05e7\u05d9\u05d9\u05df \u05d9\u05e2\u05e6\u05d8\u05d9\u05d2\u05e2 \u05d0\u05d9\u05e0\u05e4\u05d0\u05e8\u05de\u05d0\u05e6\u05d9\u05e2 \u05d3\u05e2\u05e8\u05d5\u05d9\u05e3. FindMTL \u05d0\u05d9\u05d6 \u05d3\u05e2\u05e8 \u05e7\u05d4\u05d9\u05dc\u05d4 \u05d3\u05d9\u05e8\u05e2\u05e7\u05d8\u05d0\u05e8\u05d9\u05e2 \u05d5\u05d5\u05d0\u05e1 \u05d4\u05d0\u05d8 \u05e2\u05e1 \u2014 \u05d3\u05e2\u05e8 \u05dc\u05d9\u05e0\u05e7 \u05d3\u05d0 \u05d0\u05d5\u05e0\u05d8\u05df \u05e4\u05d9\u05e8\u05d8 \u05e6\u05d5\u05dd \u05e8\u05d9\u05db\u05d8\u05d9\u05d2\u05df \u05d0\u05e4\u05d8\u05d9\u05d9\u05dc. CJHQ \u05d4\u05d0\u05dc\u05d8 \u05e2\u05e1 \u05e0\u05d9\u05e9\u05d8; \u05e7\u05d5\u05e7\u05d8 \u05d3\u05d0\u05e8\u05d8 \u05e0\u05d0\u05da \u05d3\u05d9 \u05e4\u05e8\u05d8\u05d9\u05dd.'
  }, L);
  r.actions = [askFindMtlAction(hit.key, L)];
  r.sources = [askFindMtlSource(hit.key)];
  return r;
}

function askPracticalHandlers(){
  // Priority order. CJHQ's own content and structured data first, then the
  // resource matcher, and only then the FindMTL hand-off - so CJHQ never sends
  // someone elsewhere for something it already answers.
  // askOrganizations sits with the other structured CJHQ data, after the
  // emergency handler (which already owns Hatzolah) and before the resource
  // matcher, so "who do I call for X" is answered from CJHQ's own partner list
  // rather than from whichever resource happens to share a word with it.
  // askContactCjhq is first among the practical handlers: a question about
  // reaching CJHQ is about CJHQ itself, not about a partner or a resource.
  // askChildTravel sits ahead of the matcher because the words that carry its
  // meaning are not resource keywords - the matcher saw only noise.
  return [askContactCjhq, askEruv, askEmergency, askZmanim, askCalendar,
          askOrganizations, askChildTravel, askSpecialInfo,
          askCommunityDirectory, askCjhqResources, askFindMtl];
}

function askHalachic(q, opts){
  if(!ASK_HALACHIC_RE.test(String(q || ''))) return null;
  const L = askDetectLanguage(q);

  // Still give the person what CJHQ genuinely knows. The practical handlers
  // run exactly as they normally would; only the presentation changes.
  let practical = null;
  for(const h of askPracticalHandlers()){
    const out = h(q, opts);
    if(out){ practical = out; break; }
  }

  const r = practical || askAnswerShape();
  r.lang = L;
  r.halachic = true;
  r.handled = true;
  r.handler = practical ? ('Halachic + ' + (practical.handler || 'none')) : 'Halachic';

  const referral = askT({
    en:'CJHQ can provide practical, travel and government information, but does not provide halachic rulings. For the halachic ruling on this question, please consult your rov.',
    fr:'Le CJHQ peut fournir des renseignements pratiques, de voyage et gouvernementaux, mais ne donne pas de d\u00e9cisions halakhiques. Pour la d\u00e9cision halakhique concernant cette question, veuillez consulter votre rav.',
    he:'CJHQ \u05d9\u05db\u05d5\u05dc \u05dc\u05e1\u05e4\u05e7 \u05de\u05d9\u05d3\u05e2 \u05de\u05e2\u05e9\u05d9, \u05de\u05d9\u05d3\u05e2 \u05d1\u05e0\u05d5\u05e9\u05d0\u05d9 \u05e0\u05e1\u05d9\u05e2\u05d5\u05ea \u05d5\u05de\u05d9\u05d3\u05e2 \u05de\u05de\u05e9\u05dc\u05ea\u05d9, \u05d0\u05da \u05d0\u05d9\u05e0\u05d5 \u05e0\u05d5\u05ea\u05df \u05e4\u05e1\u05e7\u05d9 \u05d4\u05dc\u05db\u05d4. \u05dc\u05e7\u05d1\u05dc\u05ea \u05d4\u05db\u05e8\u05e2\u05d4 \u05d4\u05dc\u05db\u05ea\u05d9\u05ea \u05d1\u05e9\u05d0\u05dc\u05d4 \u05d6\u05d5, \u05d9\u05e9 \u05dc\u05d4\u05ea\u05d9\u05d9\u05e2\u05e5 \u05e2\u05dd \u05d4\u05e8\u05d1 \u05e9\u05dc\u05db\u05dd.',
    yi:'CJHQ \u05e7\u05e2\u05df \u05e6\u05d5\u05e9\u05d8\u05e2\u05dc\u05df \u05e4\u05e8\u05d0\u05e7\u05d8\u05d9\u05e9\u05e2, \u05e8\u05d9\u05d9\u05d6\u05e2 \u05d0\u05d5\u05df \u05e8\u05e2\u05d2\u05d9\u05e8\u05d5\u05e0\u05d2\u05e1\u05be\u05d0\u05d9\u05e0\u05e4\u05d0\u05e8\u05de\u05d0\u05e6\u05d9\u05e2, \u05d0\u05d1\u05e2\u05e8 \u05d2\u05d9\u05d8 \u05e0\u05d9\u05e9\u05d8 \u05e7\u05d9\u05d9\u05df \u05d4\u05dc\u05db\u05ea\u05d9\u05e9\u05e2 \u05e4\u05e1\u05e7\u05d9 \u05d3\u05d9\u05df. \u05e4\u05d0\u05e8 \u05d3\u05e2\u05e8 \u05d4\u05dc\u05db\u05ea\u05d9\u05e9\u05e2\u05e8 \u05d4\u05db\u05e8\u05e2\u05d4 \u05d0\u05d9\u05df \u05d3\u05e2\u05e8 \u05e9\u05d0\u05dc\u05d4, \u05d1\u05d9\u05d8\u05e2 \u05e4\u05e8\u05e2\u05d2\u05d8 \u05d0\u05d9\u05d9\u05e2\u05e8 \u05e8\u05d1.'
  }, L);

  const label = askT({
    en:'Practical information from CJHQ:',
    fr:'Renseignements pratiques du CJHQ :',
    he:'\u05de\u05d9\u05d3\u05e2 \u05de\u05e2\u05e9\u05d9 \u05de-CJHQ:',
    yi:'\u05e4\u05e8\u05d0\u05e7\u05d8\u05d9\u05e9\u05e2 \u05d0\u05d9\u05e0\u05e4\u05d0\u05e8\u05de\u05d0\u05e6\u05d9\u05e2 \u05e4\u05d5\u05df CJHQ:'
  }, L);

  r.answer = (practical && practical.answer)
    ? (label + '\n' + practical.answer + '\n\n' + referral)
    : referral;
  return r;
}


/* ---------- FindMTL: the community-directory fallback ----------
   FindMTL is a DESTINATION, not a source. Nothing from it is copied into CJHQ
   and nothing here summarises its listings - the assistant names the category
   and hands over the link.

   These eight URLs are the complete approved set. Do not add a ninth from
   inference: an invented directory URL fails the same way an invented phone
   number does, and this is the kind of question people act on immediately. */
