  { id:'israel',         match:/israel|isra\u00ebl|\u05d9\u05e9\u05e8\u05d0\u05dc|\u05d0\u05e8\u05e5 \u05d9\u05e9\u05e8\u05d0\u05dc/i },
  { id:'united-kingdom', match:/united kingdom|\bu\.?k\.?\b|britain|england|royaume-uni|angleterre|\u05d0\u05e0\u05d2\u05dc\u05d9\u05d4|\u05d1\u05e8\u05d9\u05d8\u05e0\u05d9\u05d4/i },
  { id:'european-union', match:/european union|\be\.?u\.?\b|europe|union europ\u00e9enne|\u05d0\u05d9\u05e8\u05d5\u05e4\u05d4/i }
