  'refuah v\'chesed':    ['refuah vchesed', 'refuah v chesed', 'refuah', '\u05e8\u05e4\u05d5\u05d0\u05d4 \u05d5\u05d7\u05e1\u05d3'],
  'yad ve\'ezer':        ['yad veezer', 'yad ve ezer', 'yad vaezer', '\u05d9\u05d3 \u05d5\u05e2\u05d6\u05e8'],
